export const technologyGroups = [{"name":"Quantenfundamente & Lichttechnologie","level":"Forschung","foundation":"Quantenoptik, Photonik und Licht-Materie-Wechselwirkung bilden die Grundlage. Ein Laboraufbau beginnt mit stabiler optischer Bank, geeigneter Laserquelle, Strahlformung, Detektion und thermischer sowie mechanischer Stabilisierung.","mechanism":"Photonen werden durch optische Elemente präpariert, geführt und gemessen. Interferenz, Polarisation, Resonatoren und nichtlineare Effekte bestimmen die Funktion; Quantenzustände sind empfindlich gegen Verluste und Dekohärenz.","hardware":"Laser oder LED je nach Experiment, Spiegel, Linsen, Strahlteiler, optische Fasern, Photodioden oder Einzelphotonendetektoren, Spektrometer, optischer Tisch, Temperaturkontrolle.","software":"Python, NumPy, SciPy, QuTiP, LabVIEW oder Hersteller-SDK; Geräte-Treiber, Kalibrierung, Messdatenerfassung, Fehleranalyse und reproduzierbare Versuchsprotokolle.","build":"Mit klassischer Optik beginnen; Strahlengang simulieren; Komponenten aufbauen und justieren; Leistung und Spektrum messen; Störquellen quantifizieren; erst danach Einzelphotonen- oder Quantenexperimente ergänzen.","maturity":"Teilweise etabliert; einzelne Quantenanwendungen sind Forschung oder frühe Kommerzialisierung."},{"name":"Nano-, Material- & programmierbare Materie","level":"Forschung","foundation":"Die Entwicklung reicht von Dünnschichten und Nanostrukturen bis zu Metamaterialien, MEMS und programmierbaren Materialverbünden. Entscheidend sind Herstellbarkeit, Toleranzen, Grenzflächen und Skalierung.","mechanism":"Struktur-Eigenschafts-Beziehungen entstehen durch Geometrie, Zusammensetzung und Oberflächen. Lithografie, Abscheidung, Ätzen und Selbstorganisation erzeugen definierte Strukturen, deren Verhalten anschließend charakterisiert wird.","hardware":"Reinraumzugang, Substrate, Resists, Masken, Beschichtungs- und Ätzanlagen, Elektronenmikroskopie, AFM, Profilometer, Schutz- und Abfallmanagement.","software":"CAD, COMSOL, Lumerical, Python, Materials Project-Daten, Prozessrezepte, Bildanalyse und statistische Qualitätskontrolle.","build":"Anforderung festlegen; Material und Prozess auswählen; Struktur simulieren; Testcoupon fertigen; mikroskopisch vermessen; mechanische, optische und thermische Eigenschaften prüfen; Prozessfenster dokumentieren.","maturity":"Teilweise etabliert; nanoskalige Fertigung benötigt Speziallabore."},{"name":"KI, Software & Quantenrechnen","level":"Entwicklung","foundation":"Eine modulare KI- und Rechenplattform verbindet Datenaufnahme, Modellierung, Simulation, sichere Dienste und nachvollziehbare Entscheidungsunterstützung. Quantenrechner werden als spezialisierte Beschleuniger geprüft, nicht als universeller Ersatz klassischer Rechner.","mechanism":"Daten werden validiert, in reproduzierbare Pipelines überführt und von Modellen verarbeitet. Quantenalgorithmen benötigen geeignete Hardware, Fehlerkontrolle und Problemstrukturen; klassische Simulation ist oft der erste Schritt.","hardware":"GPU-Server, CPU-Cluster, RAM, SSD/NVMe, Netzwerk, optional Quantenhardware-Zugang über Cloud-Schnittstellen, HSM und Backup-Systeme.","software":"Python, PyTorch, JAX, scikit-learn, Qiskit oder Cirq, Docker, Kubernetes, PostgreSQL, Vector Search, Monitoring, CI/CD, IAM und Audit-Logs.","build":"Use Case und Qualitätsmaß definieren; Daten-Governance aufsetzen; Baseline bauen; Modell evaluieren; Bedrohungsmodell erstellen; APIs versionieren; Last- und Sicherheitstests; Betrieb überwachen.","maturity":"Klassische KI etabliert; fehlertolerantes Quantenrechnen noch Forschungsziel."},{"name":"Energie, Antriebe & industrielle Systeme","level":"Entwicklung","foundation":"Energieversorgung und Antriebssysteme müssen über Wirkungsgrad, Leistung, Masse, Wärmeabfuhr, Zuverlässigkeit und Lebenszykluskosten dimensioniert werden.","mechanism":"Energie wird umgewandelt, gespeichert und über Leistungselektronik geregelt. Für Raumfahrtantriebe unterscheiden sich chemische, elektrische und Segelkonzepte deutlich bei Schub, spezifischem Impuls und Energiebedarf.","hardware":"PV-Module, Batterien, Brennstoffzellen, Inverter, Motoren, Sensoren, Leistungshalbleiter, Kühlung, Prüfstände und geeignete Sicherheitsabschaltungen.","software":"MATLAB/Simulink, OpenModelica, SPICE, Python, BMS-Firmware, PLC/SCADA, Telemetrie, digitale Zwillinge und Fehlermanagement.","build":"Lastprofil erfassen; Energie- und Wärmebilanz rechnen; Komponenten dimensionieren; Schutzkonzept erstellen; Prüfstand aufbauen; Effizienz und Lebensdauer messen; Normen und Zulassung beachten.","maturity":"Viele Teiltechnologien etabliert; Hochleistungs- und Raumfahrtsysteme hochspezialisiert."},{"name":"Robotik, autonome Systeme & Fertigung","level":"Entwicklung","foundation":"Autonome Maschinen benötigen robuste Mechanik, Sensorfusion, Regelung, sichere Bewegungsplanung und Wartbarkeit. Von Laborrobotern bis zu orbitalen Montagearmen gelten dieselben Systemprinzipien.","mechanism":"Sensoren erfassen Zustand und Umgebung; ein Zustandsmodell schätzt Position und Bewegung; Regler und Planer erzeugen Aktionen; Sicherheitssteuerungen begrenzen gefährliche Zustände.","hardware":"Aktuatoren, Getriebe, Encoder, Kameras, LiDAR, IMU, Greifer, Steuerrechner, Not-Aus, Energieversorgung und mechanische Schutzvorrichtungen.","software":"ROS 2, C++/Python, MoveIt, Gazebo/Isaac Sim, SLAM, Echtzeitsteuerung, CAN/EtherCAT, Zustandsdiagnose und sichere Update-Pipeline.","build":"Aufgabenraum definieren; digitalen Zwilling erstellen; Mechanik und Sensorik integrieren; Simulation validieren; stufenweise testen; sichere Betriebszonen und manuelle Übersteuerung vorsehen.","maturity":"Industrielle Robotik etabliert; autonome Weltraumfertigung experimentell."},{"name":"Biotechnologie, Medizin & Ökosysteme","level":"Forschung","foundation":"Bioregenerative Lebenserhaltung und Bioengineering verbinden Biologie mit Prozesskontrolle. Forschung muss Biosicherheit, Ethik, Reproduzierbarkeit und Umweltfolgen berücksichtigen.","mechanism":"Biologische Systeme wandeln Stoffe und Energie über Stoffwechselwege um. Sensorik und Prozessregelung halten Temperatur, pH, Nährstoffe und Gaswechsel in definierten Bereichen.","hardware":"Sterile Bioreaktoren, Sensoren, Filter, Pumpen, Kulturgefäße, Mikroskopie, Analytik, sterile Verbrauchsmaterialien und Biosicherheitsausrüstung.","software":"LIMS, Python/R, Bioinformatik-Pipelines, Prozessleitsysteme, Bildanalyse, Modellierung von Stoffbilanzen und Datenintegrität.","build":"Nur mit zugelassenem Labor und Fachaufsicht arbeiten; Organismus und Risiko bewerten; geschlossene Testsysteme aufbauen; Kontamination überwachen; Stoffbilanzen prüfen; Abfall validiert inaktivieren.","maturity":"Medizinische und industrielle Biotech etabliert; geschlossene planetare Ökosysteme in Forschung."},{"name":"Raumfahrt, Habitate & planetare Infrastruktur","level":"Konzept / Entwicklung","foundation":"Planetare Infrastruktur wird aus Missionsprofil, Strahlungsumgebung, Schwerkraft, Staub, Temperatur, Ressourcenlage und Logistik abgeleitet. Vor Ort verfügbare Ressourcen können Transportmasse reduzieren.","mechanism":"Habitate benötigen Druckhülle, thermische Kontrolle, Lebenserhaltung, Strahlenschutz, Energie, Kommunikation und Redundanz. ISRU verarbeitet lokale Rohstoffe nur, wenn Qualität und Energiebedarf nachgewiesen sind.","hardware":"Druckbehälter, Regolith- oder Eisverarbeitung, Solarfelder, Reaktoren nach Zulassung, Wärmetauscher, Luft- und Wasseraufbereitung, Sensoren, Schleusen und Rover.","software":"CAD/FEA, Systems Engineering, MBSE, NASA-Standards, Missionssimulation, autonome Diagnostik, GIS und digitale Zwillinge.","build":"Standortdaten sammeln; Gefahren- und Ressourcenkarte erstellen; Massen-/Energiebudget rechnen; unbemannte Demonstratoren testen; Habitatmodule redundant auslegen; Notfall- und Evakuierungskonzepte validieren.","maturity":"Einzelkomponenten vorhanden; dauerhafte außerirdische Siedlungen noch nicht realisiert."},{"name":"Planeten, Monde & Terraforming","level":"Konzept / Langfristvision","foundation":"Die Kapitel behandeln Welten als gekoppelte Geosysteme: Atmosphäre, Hydrologie, Geologie, Magnetfeld, Strahlung und Biosphäre. Terraforming ist kein kurzfristiges Bauprojekt, sondern eine planetare Langzeitfrage.","mechanism":"Modelle koppeln Strahlungsbilanz, Atmosphärenchemie, Wärmehaushalt, volatile Stoffe und mögliche biologische Kreisläufe. Lokale Habitate sind technisch viel realistischer als globale Klimaumformung.","hardware":"Orbiter, Lander, Wetterstationen, Bohrer, Spektrometer, Gewächshausmodule, geschlossene Wasser- und Luftkreisläufe, Strahlungsmonitore.","software":"Klimamodelle, GIS, Fernerkundung, Planetary Data System, Python, numerische Strömungssimulation und Unsicherheitsanalyse.","build":"Zuerst wissenschaftliche Baseline erstellen; lokale Ressourcen messen; kleine abgeschlossene Habitate demonstrieren; ökologische Risiken und Planetary-Protection-Regeln berücksichtigen; keine Freisetzung unbekannter Organismen.","maturity":"Lokale Habitate langfristig denkbar; globales Terraforming spekulativ und ethisch umstritten."},{"name":"Orbitale Megastrukturen & Sternenarchitektur","level":"Langfristvision","foundation":"Großstrukturen im All reichen von Solarsegeln und orbitalen Fertigungsplattformen bis zu Schwärmen von Energie-Satelliten. Die zentrale Herausforderung ist nicht nur Konstruktion, sondern Massefluss, Wartung und Kollisionsvermeidung.","mechanism":"Strukturen werden modular aus kleinen Einheiten aufgebaut. Energie, Kommunikation, Navigation und Robotik koordinieren Montage und Betrieb; Materialtransport und thermische Abstrahlung begrenzen die Skalierung.","hardware":"Leichte Verbundwerkstoffe, Strahlungs- und Thermalschutz, Solarmodule, autonome Montagearme, Antriebsmodule, Navigationssensoren, Docking-Systeme und Ersatzteilfertigung.","software":"Orbitale digitale Zwillinge, Bahnmechanik, Kollisionsanalyse, Flottensteuerung, Robotik-Stacks, Fehlertoleranz und autonome Flottenplanung.","build":"Mit kleinen CubeSat-Demonstratoren beginnen; Bahn- und Trümmermodell rechnen; modulare Schnittstellen festlegen; autonome Inspektion erproben; Montage nur mit Sicherheits- und Entsorgungsplan skalieren.","maturity":"Einzelne Bausteine etabliert; große Schwärme und Sternen-Infrastruktur hypothetisch."},{"name":"Quantenformel, ASTRALIS & spirituelle Architektur","level":"Vision / Modell","foundation":"Die Quantenformel Dis → Nichts → E, Quantenlicht, Lebensblume, Lichtkern, Merkaba, Dysfluktation und ASTRALIS Ω werden als originäre Modell- und Designideen dokumentiert. Sie können Forschung inspirieren, sind aber nicht automatisch physikalische Naturgesetze.","mechanism":"Ein Konzept wird operationalisiert, indem Begriffe, Zustände, Variablen, Messgrößen und Falsifikationskriterien definiert werden. Spirituelle Deutungen können als Philosophie, Kunst und Nutzererfahrung bestehen, ohne als experimentell bewiesene Physik ausgegeben zu werden.","hardware":"Für digitale Prototypen: 3D-Engine, Sensorik, LED-/Photonik-Demonstratoren, Datenlogger, optische Bauteile und sichere Stromversorgung. Für physische Experimente: Laborplanung und unabhängige Fachprüfung.","software":"Three.js, Blender, Python, Unity/Unreal, wissenschaftliche Visualisierung, Simulation, Dokumentation, Versionskontrolle und getrennte Datenräume für Messung und Interpretation.","build":"Begriffe präzisieren; überprüfbare Hypothese formulieren; Simulation und Messung trennen; Prototyp im kleinen Maßstab bauen; Ergebnisse reproduzieren; spirituelle Bedeutung als solche kennzeichnen.","maturity":"Konzeptuell; physikalische Validierung nur für konkret messbare Teilhypothesen."},{"name":"Kommunikation, Sicherheit & Zivilisationssysteme","level":"Entwicklung","foundation":"Interplanetare Zivilisation benötigt Kommunikationsnetze mit Lichtlaufzeiten, autonomer Fehlerbehandlung, Identität, Datenschutz, Energie- und Ressourcenverwaltung sowie demokratisch kontrollierten Institutionen.","mechanism":"Netze werden als verzögerungstolerante Systeme entworfen. Daten werden gespeichert, weitergeleitet, signiert und priorisiert; Sicherheit entsteht aus Identitätsmanagement, Verschlüsselung, Schlüsselrotation und überprüfbaren Prozessen.","hardware":"Antennen, optische Terminals, Router, Strahlungsresistente Rechner, redundante Stromversorgung, Bodenstationen und sichere Schlüsselmodule.","software":"Delay/Disruption Tolerant Networking, CCSDS-Protokolle, TLS, PKI, Zero Trust, Monitoring, Datenbanken, Governance- und Audit-Software.","build":"Bedrohungsmodell und Kommunikationsverzögerungen erfassen; Protokolle auswählen; Ende-zu-Ende-Integrität testen; Offline-Betrieb einplanen; Schlüsselwiederherstellung und Governance prüfen.","maturity":"Viele Bausteine etabliert; vollständige interplanetare Netze im Aufbau."},{"name":"Makroökonomie, Forschung & kosmische Gesellschaft","level":"Konzept / Entwicklung","foundation":"Technische Zivilisationen benötigen transparente Ressourcenbilanzen, offene Forschung, faire Entscheidungsprozesse und robuste Governance. ASTRALIS-Ökonomien sind Simulationen, keine realen Finanzprodukte.","mechanism":"Systemdynamik bildet Energie, Material, Bevölkerung, Transport, Forschung und ökologische Grenzen ab. Szenarien zeigen Wechselwirkungen; sie sind keine sicheren Prognosen.","hardware":"Reale Infrastruktur: Messsysteme, Rechenzentren, Energie- und Logistiknetze. Spielsystem: virtuelle Credits, Weltprofile, Forschungsbäume und Ereignis-Engine.","software":"System-Dynamics-Tools, Datenbanken, Simulations-Engine, Rollen- und Rechteverwaltung, Audit-Logs, Open-Data-Schnittstellen und barrierefreie UI.","build":"Ziele und Gemeinwohlkriterien festlegen; Ressourcenflüsse modellieren; Szenarien vergleichen; Regeln transparent machen; Spielwerte klar von realen Vermögenswerten trennen.","maturity":"Sozial-technische Modelle; kosmische Zivilisation bleibt Zukunftsszenario."}];
